const storageKey = "holus.cannp.v16.status";
const actionKey = "holus.cannp.v16.actions";
let activeFilter = "all";
let statusState = loadJson(storageKey, {});
let actionState = loadJson(actionKey, {});

function loadJson(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function saveJson(key,value){localStorage.setItem(key,JSON.stringify(value))}
function esc(value){return String(value).replace(/[&<>'"]/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[ch]))}

function renderTopics(){
  const grid=document.querySelector("#topic-grid");
  grid.innerHTML=TOPICS.map(topic=>{
    const links=topic.links.length?`<div class="detail-block"><h4>Sources</h4><div class="source-links">${topic.links.map(([label,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`).join("")}</div></div>`:"";
    const state=statusState[topic.id]||{};
    return `<article class="topic-card" data-id="${topic.id}" data-category="${topic.category}" data-search="${esc([topic.title,topic.deck,topic.issue,topic.pages,topic.categoryLabel,topic.newsletter,topic.practice].join(" ").toLowerCase())}">
      <div class="topic-top"><div class="topic-meta"><span class="category-tag">${topic.categoryLabel}</span><span class="evidence-label ${topic.labelClass}">${topic.label}</span></div><h3>${topic.title}</h3><p class="topic-deck">${topic.deck}</p><div class="source-line"><span>Issue ${topic.issue}</span><span>${topic.pages}</span></div></div>
      <button class="topic-toggle" type="button" aria-expanded="false" aria-controls="detail-${topic.id}">Open detailed study note</button>
      <div class="topic-detail" id="detail-${topic.id}" hidden>
        <div class="detail-block"><h4>What the newsletter reports</h4><p>${topic.newsletter}</p></div>
        <div class="detail-block"><h4>Evidence in context</h4><p>${topic.evidence}</p></div>
        <div class="detail-block"><h4>Within my training &amp; scope</h4><p>${topic.practice}</p></div>
        <div class="detail-block client-example"><h4>Practice example</h4><p>${topic.example}</p></div>
        <div class="detail-block"><h4>Limits &amp; referral considerations</h4><p>${topic.limits}</p></div>
        <div class="detail-block"><h4>Remember this</h4><ul class="remember-list">${topic.remember.map(item=>`<li>${item}</li>`).join("")}</ul></div>${links}
      </div>
      <div class="topic-status" aria-label="Study status for ${esc(topic.title)}"><button class="status-button ${state.read?"is-set":""}" type="button" data-status="read" aria-pressed="${!!state.read}">✓ Read</button><button class="status-button ${state.revisit?"is-set":""}" type="button" data-status="revisit" aria-pressed="${!!state.revisit}">↺ Revisit</button><button class="status-button ${state.action?"is-set":""}" type="button" data-status="action" aria-pressed="${!!state.action}">→ Action to try</button></div>
    </article>`;
  }).join("");
  grid.querySelectorAll(".topic-toggle").forEach(button=>button.addEventListener("click",()=>{
    const detail=document.getElementById(button.getAttribute("aria-controls"));
    const open=button.getAttribute("aria-expanded")==="true";
    button.setAttribute("aria-expanded",String(!open));detail.hidden=open;button.firstChild.nodeValue=open?"Open detailed study note":"Close detailed study note";
  }));
  grid.querySelectorAll(".status-button").forEach(button=>button.addEventListener("click",()=>{
    const card=button.closest(".topic-card");const id=card.dataset.id;const key=button.dataset.status;
    statusState[id] ||= {};statusState[id][key]=!statusState[id][key];
    button.classList.toggle("is-set",statusState[id][key]);button.setAttribute("aria-pressed",String(statusState[id][key]));saveJson(storageKey,statusState);updateSavedSummary();
  }));
  applyTopicFilters();updateSavedSummary();
}

function applyTopicFilters(){
  const term=document.querySelector("#topic-search").value.trim().toLowerCase();let shown=0;
  document.querySelectorAll(".topic-card").forEach(card=>{const categoryOk=activeFilter==="all"||card.dataset.category===activeFilter;const searchOk=!term||card.dataset.search.includes(term);card.hidden=!(categoryOk&&searchOk);if(!card.hidden)shown++;});
  document.querySelector("#result-count").textContent=`Showing ${shown} of ${TOPICS.length} topics`;
  document.querySelector("#empty-state").hidden=shown!==0;
}
function updateSavedSummary(){
  const counts={read:0,revisit:0,action:0};Object.values(statusState).forEach(state=>Object.keys(counts).forEach(k=>{if(state[k])counts[k]++}));
  document.querySelector("#saved-summary").textContent=`${counts.read} read · ${counts.revisit} revisit · ${counts.action} actions`;
}

function renderEvidence(){document.querySelector("#evidence-grid").innerHTML=EVIDENCE_CHECKS.map(item=>`<article class="evidence-card"><span class="evidence-label ${item.cls}">${item.label}</span><h3>${item.claim}</h3><p>${item.text}</p><a href="${item.link}" target="_blank" rel="noopener">${item.source} ↗</a></article>`).join("")}

function renderResources(){
  const term=document.querySelector("#resource-search")?.value.trim().toLowerCase()||"";const filter=document.querySelector("#resource-filter")?.value||"all";let shown=0;
  const grid=document.querySelector("#resource-grid");grid.innerHTML=RESOURCES.map(item=>{const visible=(filter==="all"||item.type===filter)&&(!term||[item.name,item.text,item.typeLabel,item.issue,item.path].join(" ").toLowerCase().includes(term));if(visible)shown++;return `<article class="resource-card" ${visible?"":"hidden"}><span class="resource-type">${item.typeLabel}</span><h3>${item.name}</h3><p>${item.text}</p><div class="resource-meta"><strong>${item.issue}</strong><br>${item.path}${item.link?`<br><a href="${item.link}" target="_blank" rel="noopener">${item.linkLabel} ↗</a>`:""}</div></article>`}).join("");
  document.querySelector("#resource-empty").hidden=shown!==0;
}

function renderNews(){document.querySelector("#news-timeline").innerHTML=NEWS.map(item=>`<article class="timeline-item"><div class="timeline-date">${item.date}</div><div><h3>${item.title}</h3><p>${item.text}</p><div class="timeline-meta"><span class="timeline-source">${item.source}</span><span class="timeline-status">${item.status}</span></div></div></article>`).join("")}

function renderRecall(){
  const list=document.querySelector("#recall-list");list.innerHTML=RECALL.map(([q,a],i)=>`<div class="recall-item"><button type="button" aria-expanded="false" aria-controls="recall-${i}">${q}</button><div class="recall-answer" id="recall-${i}" hidden>${a}</div></div>`).join("");
  list.querySelectorAll("button").forEach(button=>button.addEventListener("click",()=>{const answer=document.getElementById(button.getAttribute("aria-controls"));const open=button.getAttribute("aria-expanded")==="true";button.setAttribute("aria-expanded",String(!open));answer.hidden=open}));
}

function renderActions(){
  const list=document.querySelector("#action-list");list.innerHTML=ACTIONS.map((item,i)=>`<label class="action-item"><input type="checkbox" data-action="${i}" ${actionState[i]?"checked":""}><span>${item}</span></label>`).join("");
  list.querySelectorAll("input").forEach(input=>input.addEventListener("change",()=>{actionState[input.dataset.action]=input.checked;saveJson(actionKey,actionState)}));
}

function renderGlossary(){document.querySelector("#glossary").innerHTML=GLOSSARY.map(([term,definition])=>`<details><summary>${term}</summary><p>${definition}</p></details>`).join("")}
function renderCoverage(){document.querySelector("#coverage-body").innerHTML=COVERAGE.map(row=>`<tr>${row.map(cell=>`<td>${cell}</td>`).join("")}</tr>`).join("")}

document.querySelector("#topic-search").addEventListener("input",applyTopicFilters);
document.querySelectorAll(".filter").forEach(button=>button.addEventListener("click",()=>{activeFilter=button.dataset.filter;document.querySelectorAll(".filter").forEach(b=>{const on=b===button;b.classList.toggle("is-active",on);b.setAttribute("aria-pressed",String(on))});applyTopicFilters()}));
document.querySelector("#clear-topic-tools").addEventListener("click",()=>{document.querySelector("#topic-search").value="";activeFilter="all";document.querySelectorAll(".filter").forEach(b=>{const on=b.dataset.filter==="all";b.classList.toggle("is-active",on);b.setAttribute("aria-pressed",String(on))});applyTopicFilters()});
document.querySelector("#resource-search").addEventListener("input",renderResources);
document.querySelector("#resource-filter").addEventListener("change",renderResources);
document.querySelector("#reset-actions").addEventListener("click",()=>{actionState={};saveJson(actionKey,actionState);renderActions()});

const CANNP_VIEWS=new Set(["overview","study","practice","library","evidence","pdfs"]);

function cannpViewFromHash(){
  const hash=location.hash.replace(/^#/,"").toLowerCase();
  if(hash==="cannp-pdfs")return "pdfs";
  return CANNP_VIEWS.has(hash)?hash:"overview";
}

function setCannpView(view,options={}){
  const next=CANNP_VIEWS.has(view)?view:"overview";
  document.querySelectorAll("main > [data-cannp-view]").forEach(section=>{section.hidden=section.dataset.cannpView!==next});
  document.querySelectorAll("[data-cannp-view-button]").forEach(button=>{
    const active=button.dataset.cannpViewButton===next;
    button.classList.toggle("is-active",active);
    button.setAttribute("aria-pressed",String(active));
  });
  document.body.hidden=false;
  document.body.dataset.cannpActiveView=next;
  if(options.updateHash!==false){
    const targetHash=`#${next}`;
    if(location.hash!==targetHash)history.pushState({cannpView:next},"",targetHash);
  }
  if(options.scroll!==false){
    const reduce=window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    window.scrollTo({top:0,behavior:reduce?"auto":"smooth"});
  }
  document.dispatchEvent(new CustomEvent("cannp-view:change",{detail:{view:next}}));
  return next;
}

document.querySelectorAll("[data-cannp-view-button],[data-cannp-view-link]").forEach(control=>control.addEventListener("click",event=>{
  if(control.tagName==="A")event.preventDefault();
  setCannpView(control.dataset.cannpViewButton||control.dataset.cannpViewLink);
}));

document.addEventListener("cannp-study:render",event=>{
  const route=event.detail?.issue||"all";
  document.querySelectorAll(".study-route-jumps [data-cannp-study-jump]").forEach(button=>{
    const active=button.dataset.cannpStudyJump===route;
    button.classList.toggle("is-active",active);
    button.setAttribute("aria-pressed",String(active));
  });
});

window.addEventListener("popstate",()=>setCannpView(cannpViewFromHash(),{updateHash:false,scroll:false}));
window.addEventListener("hashchange",()=>setCannpView(cannpViewFromHash(),{updateHash:false}));
window.CANNP_SET_VIEW=setCannpView;

renderTopics();renderEvidence();renderResources();renderNews();renderRecall();renderActions();renderGlossary();renderCoverage();
setCannpView(cannpViewFromHash(),{updateHash:false,scroll:false});
